import json
import re

def repair_log_file():
    input_file = "storage/progressor/raw_eval_logs/all_transgen_logs.jsonl"
    output_file = input_file  # Overwrite the original

    print("Attempting to repair the corrupted JSONL file.")
    reconstructed_data = []

    try:
        with open(input_file, "r") as f:
            full_content = f.read().replace('\n', '')

        # Replace '}{' with '}--SPLIT--{' to create a delimiter
        split_content = full_content.replace('}{', '}--SPLIT--{').split('--SPLIT--')

        gen_map = {"489": "10", "485": "9", "480": "8", "477": "7", "472": "6"}
        reward_pattern = re.compile(r"Final Collective Reward \(sum of individual totals\): (\d+\.?\d*)")

        for fragment in split_content:
            try:
                data = json.loads(fragment)
                simple_data = {}

                # Handle my format
                if "evaluation_id" in data and "generation_id" in data:
                    simple_data["evaluation_id"] = data["evaluation_id"]
                    simple_data["generation_id"] = data["generation_id"]
                    simple_data["final_collective_reward"] = data["final_collective_reward"]
                    reconstructed_data.append(simple_data)

                # Handle Telos I's format
                elif "eval_id" in data and "log_content" in data:
                    eval_id_str = str(data["eval_id"])
                    if eval_id_str in gen_map:
                        match = reward_pattern.search(data["log_content"])
                        if match:
                            reward = float(match.group(1))
                            simple_data = {
                                "evaluation_id": data["eval_id"],
                                "generation_id": gen_map[eval_id_str],
                                "final_collective_reward": reward
                            }
                            reconstructed_data.append(simple_data)
            except (json.JSONDecodeError, KeyError):
                # Ignore fragments that are not valid JSON or missing keys
                continue

        # Sort data by generation to ensure order
        reconstructed_data.sort(key=lambda x: int(x["generation_id"]), reverse=True)

        # Write the corrected data back
        with open(output_file, "w") as f:
            for item in reconstructed_data:
                f.write(json.dumps(item) + "\n")

        print(f"Repair complete. Wrote {len(reconstructed_data)} entries to {output_file}.")

    except Exception as e:
        print(f"An error occurred during repair: {e}")

if __name__ == "__main__":
    repair_log_file()
